<script setup lang="ts">
import {computed,reactive,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useAgos} from '../stores/agos';import {available,committed,unmet,recommend,approve,reconcile,active,positive} from '../services/operations';import {today} from '../data/seed';import type {Report,ReportStatus,Delivery} from '../types';import BarChart from '../components/BarChart.vue';import CrisisMap from '../components/CrisisMap.vue';import {ArrowUpRight,ArrowRight,Plus,Search,Droplets,Users,ClipboardCheck,Truck,Clock,Check,Download,Info,Activity} from 'lucide-vue-next';
const store=useAgos(),route=useRoute(),router=useRouter();const s=computed(()=>store.state);const page=computed(()=>String(route.params.page||'dashboard'));const coordinator=computed(()=>store.role==='LGU Coordinator');const barangay=computed(()=>store.role==='Barangay Representative');const allowed=computed(()=>coordinator.value||['dashboard','deliveries'].includes(page.value)||(barangay.value&&page.value==='reports'));
const reports=computed(()=>barangay.value?s.value.reports.filter(r=>r.barangay===store.community):store.role==='Delivery Personnel'?s.value.reports.filter(r=>s.value.deliveries.some(d=>d.reportId===r.id&&d.person==='Demo delivery team')):s.value.reports);
const verified=computed(()=>reports.value.filter(r=>r.status==='Verified'));const pending=computed(()=>reports.value.filter(r=>r.status==='Pending'));const totalNeed=computed(()=>verified.value.reduce((a,r)=>a+unmet(s.value,r),0));const delivered=computed(()=>visibleDeliveries.value.reduce((a,d)=>a+d.actual,0));
const visibleDeliveries=computed(()=>s.value.deliveries.filter(d=>reports.value.some(r=>r.id===d.reportId)&&(store.role!=='Delivery Personnel'||d.person==='Demo delivery team')));
const search=ref(''),filter=ref('All statuses'),dateFilter=ref('');const filtered=computed(()=>reports.value.filter(r=>(filter.value==='All statuses'||r.status===filter.value)&&(!dateFilter.value||r.date===dateFilter.value)&&`${r.barangay} ${r.municipality} ${r.id}`.toLowerCase().includes(search.value.toLowerCase())));
const editingId=ref('');const showForm=ref(false),detail=ref<Report|null>(null),decisionReason=ref('');const reportForm=reactive({province:'Oriental Mindoro',municipality:'Calapan City',barangay:'Bucayao',households:120,population:480,local:1500,days:3,urgency:false,description:'',lat:13.38,lng:121.17});
watch(()=>store.community,v=>reportForm.barangay=v);watch(page,()=>{search.value='';filter.value='All statuses';detail.value=null;showForm.value=false});
function submit(){store.run('Water shortage report submitted',draft=>{if(!barangay.value)throw Error('Switch to Barangay Representative to submit');for(const key of ['households','population','days'] as const)if(!Number.isInteger(reportForm[key])||reportForm[key]<=0)throw Error(`${key} must be a positive whole number`);positive(reportForm.local);if(!reportForm.description.trim()||!reportForm.barangay.trim()||!reportForm.municipality.trim()||!reportForm.province.trim())throw Error('Complete location and situation fields');if(Math.abs(reportForm.lat)>90||Math.abs(reportForm.lng)>180||!Number.isFinite(reportForm.lat)||!Number.isFinite(reportForm.lng))throw Error('Enter valid coordinates');if(editingId.value){const existing=draft.reports.find(r=>r.id===editingId.value&&r.barangay===store.community);if(!existing||existing.status!=='Correction requested')throw Error('Only correction requests can be resubmitted');Object.assign(existing,reportForm,{barangay:store.community,status:'Pending',reason:'',date:today()});}else{draft.reports.push({...reportForm,barangay:store.community,id:'R-'+crypto.randomUUID().slice(0,8),date:today(),status:'Pending',reason:''});}editingId.value='';showForm.value=false;});}
function decide(status:ReportStatus){const id=detail.value?.id;store.run('Report '+status.toLowerCase(),draft=>{if(!coordinator.value)throw Error('Coordinator role required');const r=draft.reports.find(r=>r.id===id);if(!r||!['Pending','Correction requested'].includes(r.status))throw Error('Report already reviewed');if(status!=='Verified'&&!decisionReason.value.trim())throw Error('Enter a decision explanation');r.status=status;r.reason=decisionReason.value;detail.value=null;decisionReason.value='';});}
const budget=ref(24000),baseline=ref(s.value.baseline);const recommendations=computed(()=>recommend(s.value,Math.max(0,Number(budget.value)||0)));const proposed=computed(()=>recommendations.value.reduce((a,r)=>a+r.liters,0));const overrideReason=ref('');const edits=reactive<Record<string,number>>({});
function allocate(){store.run('Allocation approved by coordinator',draft=>{if(!coordinator.value)throw Error('Coordinator role required');const items=recommendations.value.map(r=>({reportId:r.report.id,liters:edits[r.report.id]??r.liters}));if(items.some((x,i)=>x.liters!==recommendations.value[i]!.liters)&&!overrideReason.value.trim())throw Error('Record a reason for modified recommendations');approve(draft,items);if(overrideReason.value)draft.audit.unshift({date:new Date().toISOString(),actor:store.role,action:'Allocation modification: '+overrideReason.value});Object.keys(edits).forEach(k=>delete edits[k]);});}
const resourceForm=reactive({name:'',liters:0});function saveResource(){store.run('Water resource added',draft=>{if(!coordinator.value)throw Error('Coordinator role required');positive(resourceForm.liters);if(!resourceForm.name.trim())throw Error('Supply location required');draft.resources.push({id:crypto.randomUUID(),...resourceForm,updated:today()});resourceForm.name='';resourceForm.liters=0;});}
function updateResource(id:string,event:Event){const value=Number((event.target as HTMLInputElement).value);store.run('Supply quantity updated',draft=>{positive(value);if(value<committed(draft,id))throw Error('Stock cannot be below reserved quantity');draft.resources.find(r=>r.id===id)!.liters=value;draft.resources.find(r=>r.id===id)!.updated=today();});}
const deliveryDetail=ref<Delivery|null>(null);const task=reactive({person:'Demo delivery team',vehicle:'Tanker 01',scheduled:today(),actual:0,status:'Completed' as 'Completed'|'Partially Delivered'|'Failed',notes:''});
function openDelivery(d:Delivery){deliveryDetail.value=d;Object.assign(task,{person:d.person||'Demo delivery team',vehicle:d.vehicle||'Tanker 01',scheduled:d.scheduled||today(),actual:d.liters,status:'Completed',notes:''});}
function assign(){store.run('Delivery assigned',draft=>{if(!coordinator.value)throw Error('Coordinator role required');const d=draft.deliveries.find(x=>x.id===deliveryDetail.value?.id);if(!d||d.status!=='Pending')throw Error('Only pending deliveries can be assigned');if(!task.person||!task.scheduled)throw Error('Personnel and schedule required');Object.assign(d,{person:task.person,vehicle:task.vehicle,scheduled:task.scheduled,status:'Assigned'});deliveryDetail.value=null;});}
function transit(){store.run('Delivery is in transit',draft=>{if(store.role!=='Delivery Personnel')throw Error('Delivery personnel role required');const d=draft.deliveries.find(x=>x.id===deliveryDetail.value?.id);if(!d||d.status!=='Assigned'||d.person!=='Demo delivery team')throw Error('Task must be assigned to your team');d.status='In Transit';deliveryDetail.value=null;});}
function complete(){store.run('Delivery reconciled and confirmed',draft=>{if(store.role!=='Delivery Personnel')throw Error('Delivery personnel role required');reconcile(draft,deliveryDetail.value!.id,task.actual,task.status,task.notes);deliveryDetail.value=null;});}
function exportCsv(){const rows=[['Report','Barangay','Status','Population','Unmet liters','Confirmed delivered'],...reports.value.map(r=>[r.id,r.barangay,r.status,r.population,unmet(s.value,r),s.value.deliveries.filter(d=>d.reportId===r.id).reduce((a,d)=>a+d.actual,0)])];const csv=rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFFSimulated Demo Data\r\n'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='agos-simulated-response.csv';a.click();URL.revokeObjectURL(url);}
const fmt=(v:number)=>v.toLocaleString();const name=(id:string)=>s.value.reports.find(r=>r.id===id)?.barangay||id;const titles:Record<string,string>={dashboard:'Response overview',reports:'Water shortage reports',map:'Water crisis map',allocation:'Allocation engine',inventory:'Water resource inventory',deliveries:'Delivery operations',analytics:'Reports & analytics'};
</script>
<template><section class="content"><template v-if="allowed"><div class="page-heading"><div><div class="eyebrow">ORIENTAL MINDORO / RESPONSE CENTER</div><h1>{{titles[page]||'Response overview'}}</h1><p>{{page==='dashboard'?'A clearer picture. A coordinated response. Every liter accounted for.':page==='allocation'?'Transparent recommendations. Equitable distribution. Human approval.':'Coordinate emergency water assistance across our communities.'}}</p></div><div class="heading-action"><span class="date-pill">{{new Date().toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric',timeZone:'Asia/Manila'})}}</span><button v-if="barangay&&page==='reports'" class="primary" @click="editingId='';showForm=true;reportForm.barangay=store.community"><Plus :size="16"/> New report</button><button v-if="page==='analytics'" class="primary" @click="exportCsv"><Download :size="16"/> Export CSV</button></div></div>
<div v-if="barangay" class="community-select"><label>Your demo barangay <select v-model="store.community"><option v-for="b in ['Bucayao','Tawiran','Pachoca','Canubing I','Biga','Ilaya']">{{b}}</option></select></label><span>Reports and deliveries are scoped to this community.</span></div>
<template v-if="page==='dashboard'"><div class="overview-banner"><div><span class="live-label"><span class="live-dot"></span> RESPONSE SNAPSHOT</span><h2>Water where it’s needed most.</h2><p>Helping communities turn verified needs into coordinated action.</p><RouterLink :to="coordinator?'/allocation':barangay?'/reports':'/deliveries'">{{coordinator?'Review water allocations':barangay?'Manage shortage reports':'View assigned deliveries'}} <ArrowRight :size="16"/></RouterLink></div><div class="water-emblem"><Droplets :size="86" :stroke-width="1"/><span>Every drop. Every community.</span></div></div>
<div class="stats"><article><div class="stat-top">Shortage reports<ClipboardCheck :size="19"/></div><strong>{{reports.length}}</strong><span><b>{{verified.length}} verified</b> · {{pending.length}} pending review</span></article><article><div class="stat-top">Available emergency supply<Droplets :size="19"/></div><strong>{{fmt(available(s))}} <small>L</small></strong><span>Uncommitted & ready to allocate</span></article><article><div class="stat-top">Water delivered<Truck :size="19"/></div><strong>{{fmt(delivered)}} <small>L</small></strong><span><b>{{visibleDeliveries.filter(d=>d.status==='Completed').length}} completed</b> distributions</span></article><article><div class="stat-top">Remaining unmet need<Users :size="19"/></div><strong>{{fmt(totalNeed)}} <small>L</small></strong><span class="orange">{{verified.filter(r=>unmet(s,r)>0).length}} communities need assistance</span></article></div>
<div class="dashboard-grid"><article class="card"><div class="card-heading"><div><h3>Community water needs</h3><p>Estimated demand and confirmed assistance · liters</p></div><RouterLink to="/analytics" v-if="coordinator">View analytics <ArrowUpRight :size="14"/></RouterLink></div><BarChart :labels="verified.map(r=>r.barangay)" :values="verified.map(r=>Math.max(0,r.population*s.baseline-r.local))" :second="verified.map(r=>s.deliveries.filter(d=>d.reportId===r.id).reduce((a,d)=>a+d.actual,0))"/></article><article class="card pipeline"><div class="card-heading"><div><h3>Response pipeline</h3><p>From report to relief</p></div><Activity :size="18"/></div><div v-for="(v,i) in [{label:'Awaiting verification',count:pending.length,color:'amber'},{label:'Verified communities',count:verified.length,color:'teal'},{label:'Active deliveries',count:visibleDeliveries.filter(active).length,color:'blue'},{label:'Completed deliveries',count:visibleDeliveries.filter(d=>d.status==='Completed').length,color:'green'}]" class="pipeline-row"><span :class="['step',v.color]">{{i+1}}</span><span>{{v.label}}</span><strong>{{v.count}}</strong></div><div class="pipeline-note"><Info :size="15"/> Allocation requires coordinator approval.</div></article></div>
<article class="card"><div class="card-heading"><div><h3>Communities in focus</h3><p>Verified shortage reports requiring coordinated response</p></div><RouterLink :to="coordinator?'/map':'/reports'">View all communities <ArrowRight :size="14"/></RouterLink></div><div class="table-scroll"><table><thead><tr><th>COMMUNITY</th><th>AFFECTED PEOPLE</th><th>UNMET NEED</th><th>PRIORITY</th><th>STATUS</th></tr></thead><tbody><tr v-for="r in verified"><td><b>{{r.barangay}}</b><small>{{r.municipality}}</small></td><td>{{fmt(r.population)}}</td><td>{{fmt(unmet(s,r))}} L</td><td><span :class="['badge',r.urgency?'amber':'neutral']">{{r.urgency?'Elevated':'Standard'}}</span></td><td><span class="badge teal">{{s.deliveries.some(d=>d.reportId===r.id&&active(d))?'Assistance committed':'Verified'}}</span></td></tr></tbody></table></div></article></template>
<template v-else-if="page==='reports'"><div class="toolbar"><label class="search"><Search :size="17"/><input v-model="search" placeholder="Search community or report…" aria-label="Search reports"></label><select v-model="filter" aria-label="Filter status"><option>All statuses</option><option>Pending</option><option>Verified</option><option>Rejected</option><option>Correction requested</option></select><input type="date" v-model="dateFilter" aria-label="Filter submission date"></div><article class="card"><div class="table-scroll"><table><thead><tr><th>REPORT / COMMUNITY</th><th>POPULATION</th><th>LOCAL WATER / DAY</th><th>SUBMITTED</th><th>STATUS</th><th></th></tr></thead><tbody><tr v-for="r in filtered"><td><b>{{r.barangay}}</b><small>{{r.id}} · {{r.municipality}}</small></td><td>{{fmt(r.population)}}</td><td>{{fmt(r.local)}} L</td><td>{{r.date}}</td><td><span :class="['badge',r.status==='Verified'?'teal':'amber']">{{r.status}}</span></td><td><button class="text-button" @click="detail=r;decisionReason=''">Review <ArrowUpRight :size="14"/></button></td></tr></tbody></table><p v-if="!filtered.length" class="empty">No reports match these filters.</p></div></article></template>
<template v-else-if="page==='map'"><div class="info-strip"><Info :size="18"/> Real geographic context. All shortage, population, and delivery figures are fictional.</div><article class="card"><CrisisMap :reports="verified" :needs="verified.map(r=>unmet(s,r))"/></article><div class="community-cards"><article class="card" v-for="r in verified"><span :class="['badge',r.urgency?'amber':'teal']">{{r.urgency?'Elevated urgency':'Standard priority'}}</span><h3>{{r.barangay}}</h3><p>{{fmt(r.population)}} affected people · {{fmt(unmet(s,r))}} L unmet</p><small>{{r.lat.toFixed(4)}}° N, {{r.lng.toFixed(4)}}° E</small><p>{{s.deliveries.filter(d=>d.reportId===r.id).map(d=>d.status).join(' · ')||'Awaiting allocation'}}</p></article></div></template>
<template v-else-if="page==='allocation'"><div class="info-strip"><Info :size="18"/> Decision support, with required coordinator approval. This is a deterministic calculation, not a trained AI model.</div><div class="allocation-grid"><article class="card padded"><h3>Planning assumptions</h3><p>One-day emergency planning window</p><label>Liters per person per day<input type="number" v-model.number="baseline" min="1" max="100"></label><button class="secondary" @click="store.run('Planning baseline updated',d=>{if(!Number.isFinite(baseline)||baseline<=0||baseline>100)throw Error('Baseline must be between 1 and 100');d.baseline=baseline})">Apply baseline</button><p class="muted">15 L is an illustrative, configurable planning assumption, not a universal operational rule.</p><label>Dispatch budget (liters)<input type="number" v-model.number="budget" min="0" :max="available(s)"></label><small>Inventory ceiling: {{fmt(available(s))}} L</small><hr><h3>How recommendations work</h3><p class="formula">Population × {{s.baseline}} L - local water - confirmed deliveries - active commitments</p><p>Scarce supply is proportional to each verified community’s eligible unmet need. Whole liters use largest-remainder rounding; ties use report ID.</p><p>Verified urgency is shown for coordinator review. It does not silently change proportional shares. Dispatch budget represents this run’s delivery capacity.</p></article><article class="card"><div class="card-heading"><div><h3>Recommended distribution</h3><p>{{fmt(proposed)}} L recommended · {{fmt(totalNeed)}} L verified unmet need</p></div><span class="badge teal">Explainable</span></div><div class="table-scroll"><table><thead><tr><th>COMMUNITY / BASIS</th><th>ELIGIBLE NEED</th><th>ALLOCATE (L)</th><th>REMAINING</th></tr></thead><tbody><tr v-for="row in recommendations"><td><b>{{row.report.barangay}}</b><small>{{row.report.urgency?'Verified elevated urgency':'Verified standard urgency'}} · proportional share</small></td><td>{{fmt(row.need)}} L</td><td><input class="allocation-input" type="number" min="0" :max="row.need" :value="edits[row.report.id]??row.liters" @input="edits[row.report.id]=Number(($event.target as HTMLInputElement).value)" :aria-label="'Allocation for '+row.report.barangay"></td><td>{{fmt(Math.max(0,row.need-(edits[row.report.id]??row.liters)))}} L</td></tr></tbody></table><p v-if="!recommendations.length" class="empty">All verified needs are covered by deliveries or active commitments.</p></div><div class="padded"><label>Reason for modified allocations<textarea v-model="overrideReason" placeholder="Required if you change recommended quantities"></textarea></label><button class="primary" :disabled="!proposed" @click="allocate"><Check :size="17"/> Approve & reserve water</button><p class="muted">Approval reserves supply and creates pending delivery tasks. Dispatch remains a separate action.</p></div></article></div></template>
<template v-else-if="page==='inventory'"><div class="stats three"><article><span>Physical stock</span><strong>{{fmt(s.resources.reduce((a,r)=>a+r.liters,0))}} <small>L</small></strong></article><article><span>Reserved for delivery</span><strong>{{fmt(committed(s))}} <small>L</small></strong></article><article><span>Uncommitted supply</span><strong>{{fmt(available(s))}} <small>L</small></strong></article></div><article class="card"><div class="card-heading"><h3>Emergency water reserves</h3><span class="badge teal">Simulated inventory</span></div><div class="table-scroll"><table><thead><tr><th>SUPPLY LOCATION</th><th>PHYSICAL STOCK (L)</th><th>RESERVED</th><th>UNCOMMITTED</th><th>UPDATED</th></tr></thead><tbody><tr v-for="r in s.resources"><td><b>{{r.name}}</b><small>{{r.liters-committed(s,r.id)>0?'Available':'Fully reserved / depleted'}}</small></td><td><input type="number" :value="r.liters" :min="committed(s,r.id)" @change="updateResource(r.id,$event)" :aria-label="r.name+' physical stock'"></td><td>{{fmt(committed(s,r.id))}} L</td><td>{{fmt(r.liters-committed(s,r.id))}} L</td><td>{{r.updated}}</td></tr></tbody></table></div></article><form class="card padded inline-form" @submit.prevent="saveResource"><h3>Add simulated supply</h3><label>Supply location<input v-model="resourceForm.name" required></label><label>Available liters<input v-model.number="resourceForm.liters" type="number" min="0" required></label><button class="primary"><Plus :size="16"/> Add resource</button></form></template>
<template v-else-if="page==='deliveries'"><div class="info-strip"><Truck :size="18"/> {{barangay?'Track assistance assigned to your barangay.':coordinator?'Assign approved allocations to a delivery team. Confirmed quantities reconcile physical stock.':'Your team: Demo delivery team. Start an assigned trip, then confirm actual water delivered.'}}</div><div class="community-cards"><article class="card padded delivery-card" v-for="d in visibleDeliveries"><div class="card-heading"><span :class="['badge',d.status==='Completed'?'teal':'amber']">{{d.status}}</span><Truck :size="21"/></div><h3>{{name(d.reportId)}}</h3><div class="delivery-liters">{{fmt(d.liters)}} <small>L allocated</small></div><p>{{d.person||'Awaiting assignment'}} · {{d.vehicle||'No vehicle assigned'}}</p><p>Scheduled: {{d.scheduled||'Not yet scheduled'}}</p><p v-if="!active(d)">Confirmed: {{fmt(d.actual)}} L · {{d.completed.slice(0,10)}}<br>{{d.notes}}</p><button class="secondary" @click="openDelivery(d)">Open delivery <ArrowRight :size="15"/></button></article></div><p v-if="!visibleDeliveries.length" class="empty">No delivery tasks yet. Approved allocations will appear here.</p></template>
<template v-else-if="page==='analytics'"><div class="stats three"><article><span>Verified unmet need</span><strong>{{fmt(totalNeed)}} <small>L</small></strong></article><article><span>Active allocations</span><strong>{{fmt(committed(s))}} <small>L</small></strong></article><article><span>Delivery completion rate</span><strong>{{visibleDeliveries.length?Math.round(visibleDeliveries.filter(d=>d.status==='Completed').length/visibleDeliveries.length*100):0}}<small>%</small></strong></article></div><div class="dashboard-grid"><article class="card padded"><h3>Reports by status</h3><BarChart :labels="['Pending','Verified','Rejected','Correction requested']" :values="['Pending','Verified','Rejected','Correction requested'].map(x=>s.reports.filter(r=>r.status===x).length)"/></article><article class="card padded"><h3>Demand, supply & delivery</h3><BarChart :labels="['Unmet need','Free supply','Committed','Delivered']" :values="[totalNeed,available(s),committed(s),delivered]"/></article></div><article class="card"><div class="card-heading"><h3>Allocation & delivery history</h3></div><div class="table-scroll"><table><thead><tr><th>COMMUNITY</th><th>ALLOCATED</th><th>ACTUAL</th><th>STATUS</th><th>CONFIRMED</th></tr></thead><tbody><tr v-for="d in s.deliveries"><td>{{name(d.reportId)}}</td><td>{{fmt(d.liters)}} L</td><td>{{fmt(d.actual)}} L</td><td>{{d.status}}</td><td>{{d.completed.slice(0,10)||'—'}}</td></tr></tbody></table></div></article><article class="card padded"><h3>Decision audit trail</h3><div class="audit-row" v-for="a in s.audit"><span class="audit-dot"></span><div><b>{{a.action}}</b><small>{{a.actor}} · {{new Date(a.date).toLocaleString('en-PH',{timeZone:'Asia/Manila'})}}</small></div></div></article></template>
</template><div v-else class="card padded"><h2>This workspace is for LGU coordinators</h2><p>Use the Demo Mode role switcher to explore this module.</p><RouterLink to="/dashboard">Return to your dashboard</RouterLink></div></section>
<div class="modal-backdrop" v-if="showForm"><form class="modal wide" @submit.prevent="submit"><div class="card-heading"><div><h2>Report a water shortage</h2><p>Simulated entries only. Do not enter citizens’ personal information.</p></div><button type="button" class="close" @click="showForm=false">×</button></div><div class="form-grid"><label>Province<input v-model="reportForm.province" required></label><label>Municipality / city<input v-model="reportForm.municipality" required></label><label>Barangay<input :value="store.community" readonly></label><label>Affected households<input type="number" min="1" v-model.number="reportForm.households" required></label><label>Affected population<input type="number" min="1" v-model.number="reportForm.population" required></label><label>Local water available (L / day)<input type="number" min="0" v-model.number="reportForm.local" required></label><label>Days of shortage<input type="number" min="1" v-model.number="reportForm.days" required></label><label>Latitude<input type="number" step="any" min="-90" max="90" v-model.number="reportForm.lat" required></label><label>Longitude<input type="number" step="any" min="-180" max="180" v-model.number="reportForm.lng" required></label></div><label class="checkbox"><input type="checkbox" v-model="reportForm.urgency"> Elevated urgency: critical community water access disruption</label><label>Situation description<textarea v-model="reportForm.description" required placeholder="Describe the simulated shortage and verification context"></textarea></label><button class="primary">Submit shortage report <ArrowRight :size="16"/></button></form></div>
<div class="modal-backdrop" v-if="detail"><section class="modal"><div class="card-heading"><div><span class="eyebrow">{{detail.id}}</span><h2>{{detail.barangay}}</h2></div><button class="close" @click="detail=null">×</button></div><span class="badge teal">{{detail.status}}</span><p>{{detail.province}} · {{detail.municipality}}</p><div class="detail-grid"><div><small>AFFECTED POPULATION</small><strong>{{fmt(detail.population)}}</strong></div><div><small>HOUSEHOLDS</small><strong>{{fmt(detail.households)}}</strong></div><div><small>LOCAL WATER / DAY</small><strong>{{fmt(detail.local)}} L</strong></div><div><small>SHORTAGE DURATION</small><strong>{{detail.days}} days</strong></div></div><p>{{detail.description}}</p><p>Urgency: {{detail.urgency?'Elevated — verify this indicator before approving':'Standard'}}</p><p>Submitted {{detail.date}} · Coordinates {{detail.lat}}, {{detail.lng}}</p><p v-if="detail.reason">Review note: {{detail.reason}}</p><button v-if="barangay&&detail.status==='Correction requested'" class="primary" @click="editingId=detail.id;Object.assign(reportForm,detail);showForm=true;detail=null">Correct &amp; resubmit report</button><template v-if="coordinator&&['Pending','Correction requested'].includes(detail.status)"><label>Review explanation<textarea v-model="decisionReason" placeholder="Required for rejection or correction request"></textarea></label><div class="button-row"><button class="primary" @click="decide('Verified')"><Check :size="16"/> Verify report</button><button class="secondary" @click="decide('Correction requested')">Request correction</button><button class="danger" @click="decide('Rejected')">Reject</button></div></template></section></div>
<div class="modal-backdrop" v-if="deliveryDetail"><section class="modal"><div class="card-heading"><h2>{{name(deliveryDetail.reportId)}} delivery</h2><button class="close" @click="deliveryDetail=null">×</button></div><p>{{fmt(deliveryDetail.liters)}} L allocated · {{deliveryDetail.status}}</p><template v-if="coordinator&&deliveryDetail.status==='Pending'"><label>Delivery personnel<select v-model="task.person"><option>Demo delivery team</option><option>Reserve demo team</option></select></label><label>Vehicle identifier<input v-model="task.vehicle"></label><label>Scheduled date<input type="date" v-model="task.scheduled"></label><button class="primary" @click="assign">Assign delivery</button></template><template v-else-if="store.role==='Delivery Personnel'&&deliveryDetail.status==='Assigned'"><p>Vehicle {{deliveryDetail.vehicle}} · Scheduled {{deliveryDetail.scheduled}}</p><button class="primary" @click="transit">Start trip · In Transit</button></template><template v-else-if="store.role==='Delivery Personnel'&&deliveryDetail.status==='In Transit'"><label>Outcome<select v-model="task.status"><option>Completed</option><option>Partially Delivered</option><option>Failed</option></select></label><label>Actual liters delivered<input type="number" min="0" :max="deliveryDetail.liters" v-model.number="task.actual"></label><label>Delivery notes<textarea v-model="task.notes" placeholder="Required for partial or failed delivery"></textarea></label><button class="primary" @click="complete">Confirm & reconcile delivery</button></template><template v-else><p>Assigned to {{deliveryDetail.person||'No team yet'}} · {{deliveryDetail.vehicle||'No vehicle'}}</p><p>Confirmed actual: {{fmt(deliveryDetail.actual)}} L</p><p>{{deliveryDetail.notes||'Use the appropriate demo role to progress this delivery.'}}</p></template></section></div>
</template>
